@dataclass
class StockConfig:
    # ---- 데이터 ----
    START: str = "2015-01-01"          # 특성 워밍업(200일선·자기이력 백분위)에 3년 여유를 둔다
    EVAL_START: str = "2018-01-01"     # 채점 시작 — M·S·I와 같은 창
    END: Optional[str] = None          # None이면 최신
    CACHE_DIR: str = "./_stock_cache"
    CACHE_DAYS: int = 1                # 캐시 유효기간(일) — 같은 날 재실행은 재다운로드하지 않는다
    # [v0.3.2 R73 §1-4] 캐시 유효성을 '나이'가 아니라 '기대 마지막 개장일까지 내용이 있는가'로도 판정한다
    #   (M v1.56.0과 같은 규칙 — M이 로드돼 있으면 M.expected_last_trading_day로 위임). 기대일보다 미래의 봉
    #   (장중 미완성 봉)은 버린다. END를 지정한 실행에서는 검사하지 않는다.
    DATA_FRESHNESS_CHECK: bool = True
    UNIVERSE: Dict[str, str] = field(default_factory=lambda: dict(STOCK_UNIVERSE))
    # [v0.10.0 R98 ⚠ 사용자 지시] 추가 종목(티커 → 산업 ETF · 역할 '사용자'). 되돌리기 k_overrides={"UNIVERSE_ADD": {}} ⇒ v0.9.2 유니버스.
    UNIVERSE_ADD: Dict[str, str] = field(default_factory=lambda: dict(STOCK_UNIVERSE_ADD_R98))

    # ---- ★ 펀더멘탈 인과 처리(파일 헤더 참조) ----
    FUND_PUBLISH_LAG_DAYS: int = 60    # 발표일을 모를 때 기간말에 더하는 보수 지연(10-K 기한 60일)
    USE_EARNINGS_DATES: bool = True    # 실제 발표일을 우선 사용
    #   [v0.2.1] 60 → 100. K1(어닝 기반 펀더멘탈)이 EPS YoY·TTM YoY·가속을 이 원장으로 만들므로
    #   분기 수가 곧 **측정 가능 구간**이다. 리포트 05 시트에서 실측된 상한이 100분기(2002년부터)였다.
    #   60이면 약 14년, 100이면 약 25년 — 자기이력 분위의 워밍업이 평가창 시작 전에 끝난다.
    #   ⚠ 되돌리기: k_overrides={"EARNINGS_LIMIT": 60}
    EARNINGS_LIMIT: int = 100          # get_earnings_dates(limit=) — 과거 분기를 최대한 받는다

    # ---- 특성 ----
    OWN_PCT_MIN_HIST: int = 250        # 자기이력 백분위 최소 관측(1년)
    HORIZONS: Tuple[int, ...] = (1, 5, 21, 63)
    VOL_WIN: int = 21
    DD_WIN: int = 63
    MA_LONG: int = 200

    # ---- [v0.2.0 K2 ★★ 라이브 규칙 전환] ----
    #   "ext200"(v0.1.0) → **"base1_cut"**. 이유는 파일 헤더 참조 — 200일선은 03 시트 측정에서
    #   정밀−기저 −0.0198 · 8/28종목 · 연도비율 0.147 · 향후수익 격차 **+0.994%p**로 **반대 방향**이었고,
    #   19 시트에서 상승구간 786개 중 미참여 190개 · 중위 대응 지연 12.5거래일로 **양쪽에서 다 늦었다**.
    #   base1_cut의 뜻: **기본 비중 1.0**에서 시작해(사용자 요구 "상승을 타서 비중 최대로")
    #     CUT_RULES의 하락 신호가 켜진 날만 CUT_WEIGHT로 감축한다.
    #   선택지: "base1_cut"(라이브) | "ext200"(v0.1.0) | "always"(항상 1.0 = B&H 대조군)
    #   ⚠ 되돌리기: k_overrides={"LIVE_RULE": "ext200"} 또는 {"LIVE_RULE": "always"}
    LIVE_RULE: str = "base1_cut"
    #   감축에 쓰는 규칙 — **03 시트에서 정밀−기저 > 0으로 측정된 것만** 넣는다(rule_matrix의 키).
    #   리포트 실측(h=21 · 29종목 집계): E3 +0.0481(16/25종목) · P2 +0.0278(16/28 · 연도비율 0.548) ·
    #     E2 +0.0193(20/28종목 — 종목 폭이 가장 넓다). E1(+0.0243)은 E2·E3와 겹쳐 제외.
    #   ⚠ 여기에 P1·P3·P4·P5를 넣지 않는다 — 전부 측정상 음수다(추세·고변동성은 개별 주식 하락을 못 맞춘다).
    #
    #   ★★ v0.2.1 정정 — **점화 빈도를 보지 않고 규칙을 고른 것이 내 설계 오류였다.**
    #     회귀 테스트가 잡았다: 위 3규칙을 OR로 묶으면 평균노출이 **0.4942**로, 대체하려던
    #     ext200(0.5866)보다 **오히려 낮다.** 원인은 명백하다 —
    #       P2 = "vol21 자기이력 **하위 1/3**"  → 정의상 약 33%의 날에 점화
    #       E2 = "서프라이즈 자기이력 **하위 1/3**" → 정의상 약 33%의 날에 점화
    #     세 신호의 합집합은 1 − 0.67×0.67×0.85 ≈ **0.6**, 즉 **60%의 날을 잘라낸다.**
    #     분위 버킷 규칙은 '위험 이벤트'가 아니라 **상태 배분기**다. 정밀−기저가 양수라는 것은
    #     "이 상태에서 하락이 조금 더 흔하다"는 뜻일 뿐, "지금 나가라"는 뜻이 아니다.
    #     사용자 요구가 "상승을 타서 비중 최대로"인데 기본 1.0에서 출발한 규칙이 40%만 들고 있으면
    #     **요구와 반대 방향**이다. 그래서 라이브에는 **이벤트 모양의 규칙만** 남긴다.
    #   라이브 = E3 하나. 이유 세 가지:
    #     (1) 정밀−기저 **+0.0481**로 측정된 것 중 **가장 높다**(16/25종목).
    #     (2) 점화 구간이 **발표 후 21거래일**로 한정된 **이벤트**다 — 분위 버킷과 성질이 다르다.
    #     (3) 향후수익 격차 **−1.450%p**로 방향이 맞다(하락 쪽으로 치우친다).
    #   P2·E2는 **퇴출이 아니라 격자로 내린다** — CUT_MIN_AGREE=2(동시 2개)로 묶으면 점화가
    #     급격히 줄어 라이브 후보가 될 수 있다. 그 판정은 다음 리포트의 [노출격자]가 한다.
    CUT_RULES: Tuple[str, ...] = ("E3 발표 후 21일 이내 & 서프라이즈<0",)
    #   여러 규칙을 쓸 때 **몇 개가 동시에 켜져야** 감축하는가. 1 = OR(합집합) · 2 = 2개 이상 동의.
    #   S 계층의 ROTATION_MIN_AGREE=2와 같은 장치다(그쪽에서 과점화를 막은 것이 검증된 방식).
    CUT_MIN_AGREE: int = 1
    #   ★ 노출 하한 감시 — 라이브 평균노출이 이 값 미만이면 **경고를 남긴다**(자동 변경은 하지 않는다).
    #     사용자 요구가 "비중 최대로"이므로, 감축 규칙이 이 선을 깨면 그 자체가 결함 신호다.
    #     리스크 파라미터를 조용히 바꾸지 않기 위해 경고만 하고 값은 그대로 둔다.
    CUT_EXPOSURE_FLOOR_WARN: float = 0.70
    CUT_WEIGHT: float = 0.0            # 감축일 목표비중(0.0 = 전량 회피 · 0.5 = 절반)
    # ---- [v0.4.0 R77 ★★ 위험 파라미터 — 시장 예산(M E_t) 상속] ----
    #   사용자 지시(2026-09-20) "산업별·주식별이 B&H가 피하지 못했던 하락을 모두 피했고 상승은 같이 타야 — 못 했으면 원인 분석해서 수정".
    #   원인(코드 판독): v0.3.3까지 단일 종목 라이브 = base1_cut = **기본 1.0**, E3(음의 어닝 서프라이즈 후 21일)만 0 → 평균 노출 ≈0.95.
    #     M(시장 국면)을 전혀 보지 않았다 — 2020-03·2022 같은 시장 하락을 구조적으로 피할 수 없다(B&H와 거의 같은 노출).
    #   처방: 목표비중 = min(base1_cut, M E_t) — I 계층이 R68부터 쓰는 것과 같은 시장 예산(E_t=0 날 0 · 부분 노출일 E_t · 1.0 날 1).
    #     리포트26(I) 실측: 같은 E_t 상속이 29산업 B&H 대비 복리·MDD·칼마 29/29(평균 CAGR 9.5→19.2% · MDD −50→−22%).
    #     E_t=0 날 산업 일평균 −10bp(28/29 음수) · E_t=1 날 +20bp(29/29 양수) — 시장 예산의 정보는 산업을 넘어 주식에도 걸린다.
    #   ⚠ 참여율은 내려간다(평균 노출 ≈0.95 → ≈0.55 예상) — 00D_하락상승개선비교가 매 실행 구 라이브와 나란히 판정한다.
    #   E_t 출처(순서): run(m_sig=…) → I 모듈 통로(industry_rotation.market_budget_handoff — I.run이 남김) → MARKET_BUDGET_CSV(M 일별 CSV)
    #     → 없으면 **경고 후 구 규칙**(00시트에 출처 표시 · 무음 금지). runner 무변경(사용자 지시: 산업·주식 코드만).
    #   되돌리기(v0.3.3 비트 동일): k_overrides={"MARKET_BUDGET": "none"}
    MARKET_BUDGET: str = "m_inherit"                     # "m_inherit"(라이브) | "none"(v0.3.3)
    MARKET_BUDGET_CSV: str = "market_regime_daily.csv"   # 통로가 없을 때의 폴백(M.main/export가 쓰는 일별 CSV · '목표비중' 열)
    MARKET_BUDGET_MAX_STALE_DAYS: int = 5                # E_t 마지막일이 가격 마지막일보다 이 달력일수 넘게 뒤처지면 쓰지 않는다
    # ---- [v0.4.0 R77] 00D_하락상승개선비교(I의 build_updown_improvement_compare 재사용) · 불필요 시트 제거 ----
    UPDOWN_COMPARE: bool = True
    UPDOWN_COMPARE_SMA: int = 200                        # 후보 행 '부분 노출일 추세컷'의 추세선(I 라이브와 같은 200일)
    #   04_펀더멘탈원장: 분기 재무 원장(F 계열 규칙용 — 매출 YoY 유효비율 0.017로 측정 불가 판정 · 라이브 미사용).
    #   티커별 '유효일 출처'·'선택 항목'은 02_티커요약에 이미 있다. 되돌리기: k_overrides={"REPORT_DROP_SHEETS": ()}
    REPORT_DROP_SHEETS: Tuple[str, ...] = ("04_펀더멘탈원장",)
    # ---- [v0.5.0 R78] ML 워크포워드 타이밍(진단·후보 — 라이브 아님) — I.ml_timing_walkforward 재사용(단일 출처) ----
    #   29종목 풀링 그래디언트 부스팅 · 연 1회 과거로만 재학습(엠바고 21일) · 가격 이력 START(2015)부터. 00D 블록 F·후보 2행.
    #   끄기: k_overrides={"ML_COMPARE": False}
    ML_COMPARE: bool = True
    ML_HORIZON: int = 21
    ML_MIN_TRAIN_YEARS: int = 3
    ML_SEED: int = 20260920
    # ---- [v0.6.0 R79 ★★] 임의 티커 입력 · 산업 ETF 자동 매핑 · 사전등록 홀드아웃 일반화 검증(20_일반화검증) ----
    #   사용 예: k_overrides={"TICKERS": ("AAPL", "AMD", "BRK.B")}(설계 29종목 대신) · {"EXTRA_TICKERS": ("AAPL",)}(더하기)
    #   라이브 규칙은 티커와 무관(min(base1_cut, M E_t))하다 — 매핑은 표시·배분격자(I 산업비중 연동)에만 쓴다.
    TICKERS: Tuple[str, ...] = ()            # 비어 있지 않으면 설계 유니버스 대신 이 티커들(역할 '사용자')
    EXTRA_TICKERS: Tuple[str, ...] = ()      # 설계(또는 TICKERS) 유니버스에 더할 티커(역할 '사용자')
    HOLDOUT_TICKERS: Tuple[str, ...] = tuple(sorted(STOCK_HOLDOUT_DEFAULT))   # 사전등록 홀드아웃(검증 전용 · 배분 제외)
    GENERALIZATION_CHECK: bool = True        # 홀드아웃 실행·20 시트(끄면 다운로드 29종목 절약)
    AUTO_MAP: bool = True                    # 사전등록에 없는 티커를 Yahoo 업종·섹터 → 상관 폴백으로 산업 ETF에 매핑
    AUTO_MAP_CACHE_DAYS: int = 30            # Yahoo info 캐시(CACHE_DIR/automap.json)
    AUTO_MAP_CORR_WIN: int = 504             # 상관 폴백 창(평가창 시작 전 거래일)
    AUTO_MAP_MIN_CORR: float = 0.30          # 이 미만이면 '미분류'
    GEN_PASS_SHARE_GAP: float = 0.15         # 판정 ①: 홀드아웃 칼마 개선 비율 ≥ 설계 비율 − 이 값
    GEN_ML_LTO: bool = True                  # 20 블록 C — ML 티커 제외 교차검증(설계로만 학습 → 홀드아웃 시험)
    # ---- [v0.3.0 D2 ★★ 신규] 배분층 — 전체자산 1.0 ----
    #   사용자 지시: "배분전략 거래 할거면 전체자산을 1로 해서 그걸 배분해서 각 총합이 1이되도록 하라고
    #                왜 자꾸 각 티커별로 비중이 1이냐고"
    #   v0.2.1까지 01Z 시트의 목표비중 합계가 실측 평균 **26.46**(최대 28.0)이었다 — 28배 레버리지다.
    #   라이브 "equal_fixed" = 종목마다 1/N 고정 슬리브, 감축이면 그 슬리브는 **현금**.
    #     전 종목 보유일 합계 1.0("비중 최대로") · 감축일수만큼 합계 하락("비중 최대로 감축").
