CFG = StockConfig()


# =============================================================================
# [0] 로깅 — M·S·I와 같은 형식 `[STAGE] [TIMESTAMP] key=value …`
# =============================================================================
_T0 = time.time()


def kv(**kw) -> str:
    out = []
    for k, v in kw.items():
        if isinstance(v, float):
            out.append(f"{k}={v:.4f}")
        else:
            out.append(f"{k}={v}")
    return " ".join(out)


def log(stage: str, msg: str, level: str = "info") -> None:
    lv = str(level).upper()
    order = {"DEBUG": 10, "INFO": 20, "WARNING": 30, "ERROR": 40}
    if order.get(lv, 20) < order.get(str(CFG.LOG_LEVEL).upper(), 20):
        return
    ts = time.strftime("%Y-%m-%d %H:%M:%S")
    print(f"[{lv}][STOCK:{stage}] [{ts}] (+{time.time() - _T0:6.1f}s) {msg}", flush=True)


# =============================================================================
# [1] 데이터 — yfinance 다운로드 + 로컬 캐시
# =============================================================================
def _cache_path(cfg: StockConfig, name: str) -> str:
    os.makedirs(cfg.CACHE_DIR, exist_ok=True)
    return os.path.join(cfg.CACHE_DIR, name)


def _cache_fresh(path: str, days: int) -> bool:
    if not os.path.exists(path):
        return False
    age = (time.time() - os.path.getmtime(path)) / 86400.0
    return age <= max(float(days), 0.0)


def expected_last_trading_day(now=None, M=None) -> pd.Timestamp:
    """[v0.3.2 R73 §1-4] 지금 종가가 있어야 하는 마지막 미국 개장일. M(v1.56.0+)이 있으면(인자 또는 이미 로드된
    sys.modules['market_regime_trader']) M.expected_last_trading_day로 **위임**(ET 16:00+여유 · NYSE 달력 — 단일 정본).
    없으면 보수적 사본: 오늘(로컬) 직전 평일(주말만 건너뜀 — 휴장일엔 하루 일찍 기대해 오경보 없이 한 번 더 받을 뿐)."""
    _m = M if M is not None else sys.modules.get("market_regime_trader")
    if _m is not None and hasattr(_m, "expected_last_trading_day"):
        try:
            return _m.expected_last_trading_day(now=now)
        except Exception as e:
            log("DATA", kv(event="expected_day_delegate_failed", err=type(e).__name__), level="warning")
    t = pd.Timestamp(now if now is not None else pd.Timestamp.now()).normalize()
    t -= pd.Timedelta(days=1)
    while t.weekday() >= 5:
        t -= pd.Timedelta(days=1)
    return t


def _prices_freshness(out: Dict[str, pd.DataFrame], cfg: StockConfig, where: str) -> Tuple[Dict[str, pd.DataFrame], bool, str]:
    """[v0.3.2 R73] (미래 봉 제거된 out, 뒤처짐 여부, 사유). 전 종목 중 **가장 최신 마지막일**이 기대일보다 앞이면 뒤처짐
    (한 종목의 상장폐지·결측이 매 실행 재다운로드를 부르지 않게 max로 본다). 미래 봉 = 장중 미완성 → 제거."""
    if not cfg.DATA_FRESHNESS_CHECK or cfg.END or not out:
        return out, False, ""
    try:
        exp = expected_last_trading_day()
    except Exception as e:
        log("DATA", kv(event="freshness_calendar_failed", err=type(e).__name__), level="warning")
        return out, False, ""
    n_drop = 0
    for t in list(out):
        df = out[t]
        fut = pd.DatetimeIndex(df.index).normalize() > exp
        if fut.any():
            out[t] = df.loc[~fut]
            n_drop += int(fut.sum())
    if n_drop:
        log("DATA", kv(event="partial_bar_dropped", rows=n_drop, expected=str(exp.date()), where=where,
                       note="기대 개장일 이후 봉 = 장중 미완성 봉 → 제거"))
    # [v0.3.3 R74 §1-4] '마지막일' = **유효 종가 마지막일**(Close가 빈 끝 행 = 종가 미확정 봉은 최신이 아니다).
    #   download_prices()는 이미 dropna(subset=["Close"])를 하지만, 다른 경로(구버전 캐시·외부 주입)에서 온 프레임도
    #   같은 기준으로 판정하도록 여기서 명시적으로 본다(리포트24 — 인덱스만 보던 검사 5곳이 전부 통과한 결함, 교훈 39).
    lastd: Dict[str, pd.Timestamp] = {}
    for t, df in out.items():
        if df is None or not len(df):
            continue
        if "Close" in df.columns:
            ok = pd.to_numeric(df["Close"], errors="coerce").notna().values
            if not ok.any():
                continue
            lastd[t] = pd.Timestamp(pd.DatetimeIndex(df.index)[ok].max()).normalize()
        else:
            lastd[t] = pd.Timestamp(df.index.max()).normalize()
    if not lastd:
        return out, False, ""
    mx = max(lastd.values())
    behind = sorted(t for t, d in lastd.items() if d < mx)
    if behind:   # 전체는 최신인데 일부 종목만 마지막 날 종가가 없다 — 재다운로드 루프는 만들지 않고 알린다
        log("DATA", kv(event="prices_last_close_missing", n=len(behind), tickers=",".join(behind[:8]),
                       latest=str(mx.date()), where=where,
                       note="이 종목들은 마지막 날 종가가 없다 — 패널 정렬 시 전일 값으로 채워질 수 있다"), level="warning")
    if mx < exp:
        return out, True, f"캐시 최신일(유효 종가) {mx.date()} < 기대 {exp.date()}"
    return out, False, ""


def download_prices(tickers: List[str], cfg: StockConfig) -> Dict[str, pd.DataFrame]:
    """OHLCV + 배당·분할 반영 종가. 실패한 티커는 건너뛰고 **이유를 남긴다**(조용히 빠지지 않게).
    [v0.3.2 R73] 캐시는 나이(CACHE_DAYS) **그리고** 내용(기대 개장일까지 있는가)으로 판정 · 미래 봉 제거.
    [v0.6.0 R79 ⚠ 결함 수정] 캐시가 티커 목록과 무관한 한 파일이라 **새 티커를 넣어도 옛 캐시가 그대로 돌아와** 새 티커가
      '가격 다운로드 실패'로 조용히 빠졌다. 이제 캐시에 **없는 티커만** 받아 합친다(증분) · 실패 티커는 1회 재시도."""
    failed: Dict[str, str] = {}
    want = list(dict.fromkeys(normalize_ticker(t) for t in tickers if normalize_ticker(t)))
    cp = _cache_path(cfg, f"px_{cfg.START}_{cfg.END or 'now'}.pkl")
    cached: Dict[str, pd.DataFrame] = {}
    if _cache_fresh(cp, cfg.CACHE_DAYS):
        try:
            cached = pd.read_pickle(cp)
            cached, _stale, _why = _prices_freshness(cached, cfg, where="cache")
            if _stale:
                log("DATA", kv(event="prices_cache_stale_refetch", reason=_why,
                               note="캐시 나이는 유효하지만 내용이 뒤처짐 — 재다운로드(사용자 지적: 19일인데 17일 예측)"),
                    level="warning")
                cached = {}
        except Exception as e:
            log("DATA", kv(event="cache_read_failed", err=str(e)[:120], action="재다운로드"), level="warning")
            cached = {}
    out: Dict[str, pd.DataFrame] = {t: cached[t] for t in want if t in cached}
    missing = [t for t in want if t not in out]
    if not missing:
        log("DATA", kv(event="prices_from_cache", tickers=len(out), path=os.path.basename(cp)))
        return out
    if out:
        log("DATA", kv(event="prices_cache_partial", cached=len(out), missing=len(missing),
                       tickers=",".join(missing[:12]), note="캐시에 없는 티커만 받는다(v0.6.0 증분)"))
    try:
        import yfinance as yf
    except Exception as e:
        log("DATA", kv(event="yfinance_import_failed", err=str(e)[:160],
                       suggest="pip install yfinance"), level="error")
        raise
    new: Dict[str, pd.DataFrame] = {}

    def _one(t: str) -> Tuple[Optional[pd.DataFrame], str]:
        try:
            df = yf.Ticker(t).history(start=cfg.START, end=cfg.END, auto_adjust=True,
                                      actions=True, raise_errors=False)
            if df is None or not len(df):
                return None, "빈 응답(티커 오타·상장폐지·지역 제한 확인)"
            df = df.rename(columns=str.title)
            df.index = pd.to_datetime(df.index).tz_localize(None).normalize()
            keep = [c for c in ["Open", "High", "Low", "Close", "Volume"] if c in df.columns]
            df = df[keep].dropna(subset=["Close"])
            if len(df) < 300:
                return None, f"관측 부족({len(df)} < 300 — 상장 1년 남짓 미만)"
            return df, ""
        except Exception as e:
            return None, f"{type(e).__name__}: {str(e)[:80]}"
    for t in missing:
        df, why = _one(t)
        if df is None and not why.startswith("관측 부족"):
            time.sleep(1.0)
            df, why2 = _one(t)                                  # 1회 재시도(일시 오류 · 속도 제한)
            if df is None:
                why = why2 or why
        if df is None:
            failed[t] = why
        else:
            new[t] = df
    new, _stale, _why = _prices_freshness(new, cfg, where="download")    # [v0.3.2 R73] 미래 봉 제거 + 뒤처짐 경고
    if _stale:
        log("DATA", kv(event="prices_still_stale", reason=_why, note="제공자가 아직 그 날 종가를 주지 않는다 — 진행"),
            level="warning")
    out.update(new)
    log("DATA", kv(event="prices_downloaded", ok=len(new), failed=len(failed), from_cache=len(out) - len(new),
                   detail=(";".join(f"{k}={v}" for k, v in failed.items()) or "-"),
                   start=cfg.START, end=(cfg.END or "now")), level=("warning" if failed else "info"))
    _FAILED_PX.update(failed)
    if new:
        try:
            pd.to_pickle({**cached, **new}, cp)
        except Exception as e:
            log("DATA", kv(event="cache_write_failed", err=str(e)[:100]), level="warning")
    return out


# [v0.6.0 R79] 마지막 다운로드 실패 사유(02·20 시트가 읽는다 — '왜 빠졌나'를 리포트에서 바로 본다)
_FAILED_PX: Dict[str, str] = {}


def download_fundamentals(tickers: List[str], cfg: StockConfig) -> Dict[str, Dict[str, Any]]:
    """분기 재무제표 + **실제 발표일**. 반환 구조:
      {ticker: {"q": DataFrame(기간말 × 항목), "earn": DataFrame(발표일 index, EPS·서프라이즈)}}
    ⚠ 여기서는 **아무 것도 가공하지 않는다** — 인과 처리는 build_fundamental_asof가 전담한다."""
    out: Dict[str, Dict[str, Any]] = {}
    cp = _cache_path(cfg, "fund.pkl")
    cached: Dict[str, Dict[str, Any]] = {}
    if _cache_fresh(cp, max(cfg.CACHE_DAYS, 7)):     # 재무제표는 분기마다 바뀌므로 1주 캐시
        try:
            cached = pd.read_pickle(cp)
        except Exception as e:
            log("DATA", kv(event="fund_cache_read_failed", err=str(e)[:120]), level="warning")
            cached = {}
    # [v0.6.0 R79 ⚠ 결함 수정] 증분 — 캐시에 없는 티커만 받는다(새 티커가 어닝 없이 E3 컷 없이 조용히 돌던 결함)
    out = {t: cached[t] for t in tickers if t in cached}
    todo = [t for t in tickers if t not in out]
    if not todo:
        log("DATA", kv(event="fundamentals_from_cache", tickers=len(out)))
        return out
    if out:
        log("DATA", kv(event="fundamentals_cache_partial", cached=len(out), missing=len(todo), tickers=",".join(todo[:12])))
    import yfinance as yf
    n_q = n_e = 0
    problems: Dict[str, str] = {}
    for t in todo:
        rec: Dict[str, Any] = {"q": pd.DataFrame(), "earn": pd.DataFrame()}
        tk = yf.Ticker(t)
        # (1) 분기 손익계산서 — 항목명이 버전·티커마다 달라 방어적으로 고른다
        try:
            q = None
            for attr in ("quarterly_income_stmt", "quarterly_financials"):
                try:
                    cand = getattr(tk, attr)
                except Exception:
                    cand = None
                if isinstance(cand, pd.DataFrame) and len(cand.columns):
                    q = cand
                    break
            if isinstance(q, pd.DataFrame) and len(q.columns):
                qq = q.T
                qq.index = pd.to_datetime(qq.index, errors="coerce")
                qq = qq[qq.index.notna()].sort_index()
                rec["q"] = qq
                n_q += 1
        except Exception as e:
            problems[t] = f"q:{type(e).__name__}"
        # (2) 실제 발표일 + 서프라이즈
        if cfg.USE_EARNINGS_DATES:
            try:
                e = tk.get_earnings_dates(limit=int(cfg.EARNINGS_LIMIT))
                if isinstance(e, pd.DataFrame) and len(e):
                    e = e.copy()
                    e.index = pd.to_datetime(e.index, errors="coerce")
                    try:
                        e.index = e.index.tz_localize(None)
                    except Exception:
                        pass
                    e = e[e.index.notna()].sort_index()
                    e.index = e.index.normalize()
                    rec["earn"] = e
                    n_e += 1
            except Exception as ex:
                problems[t] = problems.get(t, "") + f" earn:{type(ex).__name__}"
        out[t] = rec
    log("DATA", kv(event="fundamentals_downloaded", tickers=len(out), with_quarterly=n_q,
                   with_earnings_dates=n_e,
                   problems=(";".join(f"{k}={v.strip()}" for k, v in problems.items()) or "-"),
                   note="발표일이 없는 티커는 기간말 + FUND_PUBLISH_LAG_DAYS로 인과 처리한다"))
    try:
        pd.to_pickle({**cached, **out}, cp)
    except Exception as e:
        log("DATA", kv(event="fund_cache_write_failed", err=str(e)[:100]), level="warning")
    return out


# =============================================================================
# [v0.6.0 R79 ★★] 임의 티커 — 입력·정규화·산업 ETF 자동 매핑 · 사전등록 홀드아웃 일반화 검증
# =============================================================================
#   사용자 지시(2026-09-20) "주식은 다른 티커를 입력해도 예측이 잘되도록 설계해야돼 지금 하고 있는 티커만 잘돼면 안된다고".
#   (1) 입력: k_overrides={"TICKERS": ("AAPL", "AMD", …)}(설계 29종목 대신) · {"EXTRA_TICKERS": (…)}(더하기).
#       정규화(대문자·공백 제거·'.'→'-' — BRK.B → BRK-B). 산업 ETF가 사전등록에 없으면 자동 매핑:
#       Yahoo 업종(info['industry']) → 표(YAHOO_INDUSTRY_TO_ETF) · 없으면 Yahoo 섹터 → 섹터 ETF · 없으면 **상관 폴백**
#       (평가창 시작 **전** AUTO_MAP_CORR_WIN일의 일간수익 상관 최대 ETF — 인과) · 그래도 없으면 '미분류'.
#       매핑은 표시·배분격자(I 산업비중 연동)에만 쓰인다 — 라이브 규칙(min(base1_cut, M E_t))은 티커와 무관하다.
#   (2) 일반화 검증: 사전등록 홀드아웃 29종목(산업마다 설계 대표와 다른 1종목 — 설계에 한 번도 쓰지 않았다)을 **같은 규칙·같은 E_t**로
#       돌려 설계 집합과 나란히 판정(20_일반화검증). 홀드아웃은 배분 포트·06 포트 행·00D에 들어가지 않는다(오염 방지).
#       ML은 '티커 제외 교차검증' — 설계 종목으로만 학습해 **처음 보는** 홀드아웃 종목에서 AUC를 잰다.
#   (3) 캐시 결함 수정: 가격·펀더멘탈 캐시가 티커 목록과 무관한 한 파일이라 **새 티커를 넣어도 옛 캐시가 돌아와**
#       새 티커가 '다운로드 실패'로 조용히 빠졌다 → 캐시에 없는 티커만 받아 합친다(증분).
#   연구/교육용 도구이며 투자 자문이 아니다.
